float kSmooth(float a, float b, float x) {
  if (a == b) return x > a ? 1.0 : 0.0;
  float t = clamp((x - a) / (b - a), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}
vec4 kSmooth4(float a, float b, vec4 x) { return vec4(kSmooth(a, b, x.x), kSmooth(a, b, x.y), kSmooth(a, b, x.z), kSmooth(a, b, x.w)); }
// Amplify's rotator: (uv - 0.5) * float2x2(c, -s, s, c) + 0.5 (row vector times matrix).
vec2 kRotate(vec2 uv, float a) {
  vec2 q = uv - 0.5;
  float c = cos(a), s = sin(a);
  return vec2(q.x * c + q.y * s, -q.x * s + q.y * c) + 0.5;
}
// A fixed key light with wrap-around, for the surface (lit) shaders: billboards face the camera, so a
// plain N.L would leave most of them in shadow.
float kLight() {
  float l = dot(normalize(vNormal), normalize(vec3(0.4, 0.8, -0.45)));
  return 0.5 + 0.5 * (0.5 + 0.5 * l);
}
vec2 kUnpack(vec4 p, float scale) { return (vec2(p.r * p.a, p.g) * 2.0 - 1.0) * scale; }
vec4 shadeFragment() {
  vec2 uv = vTex0.xy;
  float r = length((uv - 0.5) * 2.0);
  float centerNoiseFade = kSmooth(0.0, 0.0, r);
  float n = mix(0.0, (texture(mNoise1, uv * mNoise1_ST.xy + mNoise1_ST.zw + uTime * mNoiseSpeed1).r + texture(mNoise, uv * mNoise_ST.xy + mNoise_ST.zw + uTime * mNoiseSpeed).r) / 2.0, centerNoiseFade);
  float noise = kSmooth(0.0, 0.426, n);
  vec4 color = mix(mColor0, mColor1, noise);
  float amount = 0.11 * kSmooth(-0.48, 0.33299999999999996, r);
  vec2 duv = uv * mDistortion_ST.xy + mDistortion_ST.zw;
  vec2 offset = kUnpack(texture(mDistortion, duv + uTime * mDistortionSpeed1), amount) + kUnpack(texture(mDistortion, duv * 0.5 + uTime * mDistortionSpeed2), amount);
  float shape = kSmooth(0.0, 1.0, texture(mAlpha, uv * mAlpha_ST.xy + mAlpha_ST.zw + offset).r);
  vec4 c = color * (shape * 1.0 * clamp(shape - noise, 0.0, 1.0)) * vColor;
  // Dissolve: Custom1.x shows the flash from the centre out, Custom1.y hides it again.
  float edge = 1.0 - r;
  float soft = 0.5;
  float dissolve = clamp(kSmooth(0.0, soft, edge + vTex0.w) + 1.0 - kSmooth(0.0, soft, edge + vTex0.z), 0.0, 1.0);
  return vec4(c.rgb, clamp(c.a - dissolve, 0.0, 1.0));
}

