vec2 kFlipbook(vec2 uv, float index) {
  float total = mGrid.x * mGrid.y;
  float i = round(mod(index, total));
  float x = round(mod(i, mGrid.x));
  float y = mGrid.y - 1.0 - round(mod((i - x) / mGrid.x, mGrid.y));
  return (uv + vec2(x, y)) / mGrid;
}
vec4 shadeFragment() {
  float frame = round(vTex0.z);
  float n = mGrid.x * mGrid.y;
  vec4 s = texture(mMainTex, kFlipbook(vTex0.xy, fract(frame / n) * n));
  // The channel holding this frame: R for the first n frames, then G, B, A.
  float v = mix(s.r, s.g, kSmooth(n - 1.0, n - 1.0, frame));
  v = mix(v, s.b, kSmooth(2.0 * n - 1.0, 2.0 * n - 1.0, frame));
  v = mix(v, s.a, kSmooth(3.0 * n - 1.0, 3.0 * n - 1.0, frame));
  v = kSmooth(0.0, 1.0, v);
  float alpha = mColor.a * vColor.a * v;
  float dissolve = vTex0.w;
  vec3 emission = mEmission.rgb * vTex0.w;
  vec3 albedo = mColor.rgb * vColor.rgb * kLight();
  return vec4(albedo + emission, alpha);
}

